.boot-specs {
  display: flex; gap: 34px; margin-top: 54px; padding-top: 24px;
  border-top: 1px solid rgba(255,255,255,.09);
  font-family: var(--mono); font-size: 10px; letter-spacing: .14em; color: #72798a;
}
.boot-specs b { display: block; font-size: 25px; color: #fff; letter-spacing: -.03em; margin-bottom: 3px; font-weight: 600; }
.boot-art { position: relative; aspect-ratio: 1; min-height: 430px; display: grid; place-items: center; }
.boot-disc {
  position: absolute; width: min(34vw, 470px); aspect-ratio: 1; border-radius: 50%;
  background:
    repeating-radial-gradient(circle at 50% 50%, rgba(255,255,255,.055) 0 1px, transparent 1px 4px),
    radial-gradient(circle at 42% 36%, #2a2e3a 0%, #12141b 45%, #050609 72%);
  box-shadow: 0 40px 100px rgba(0,0,0,.7), inset 0 0 0 1px rgba(255,255,255,.12);
}
.disc-back { transform: translate(46px, 38px) rotate(8deg); opacity: .38; }
.disc-shadow { transform: translate(-30px, 48px) scale(1.02); filter: blur(38px); opacity: .8; background: #000; }
.disc-front { animation: spin 16s linear infinite; }
.boot-grooves {
  position: absolute; inset: 5%; border-radius: 50%;
  background: repeating-radial-gradient(circle at 50% 50%, transparent 0 3px, rgba(255,255,255,.035) 3px 4px);
  mask-image: radial-gradient(circle, transparent 34%, black 36%);
}
.boot-label {
  position: absolute; inset: 31%; border-radius: 50%;
  background: linear-gradient(145deg, #ffbd62, #e66b00);
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  text-align: center; color: #221204; box-shadow: inset 0 0 0 2px rgba(0,0,0,.18), 0 0 0 7px rgba(255,255,255,.05);
}
.boot-label-top, .boot-label-bottom { font-family: var(--mono); font-size: 7px; letter-spacing: .16em; font-weight: 700; }
.boot-label-mid { font-size: clamp(28px, 4vw, 52px); line-height: 1; font-weight: 900; letter-spacing: -.06em; }
.boot-marker {
  position: absolute; width: 2px; height: 12%; left: calc(50% - 1px); top: 3%;
  background: linear-gradient(var(--a), transparent); border-radius: 2px;
}
.boot-tone { position: absolute; border-radius: 50%; border: 1px solid; opacity: .4; }
.tone-a { width: 86%; aspect-ratio: 1; border-color: rgba(255, 154, 55, .25); }
.tone-b { width: 104%; aspect-ratio: 1; border-color: rgba(69, 203, 255, .18); }
.boot-eq {
  position: absolute; bottom: 0; left: 50%; transform: translateX(-50%);
  display: flex; gap: 5px; align-items: end; height: 54px; opacity: .7;
}
.boot-eq i { width: 3px; height: var(--h); background: linear-gradient(var(--a), rgba(255,159,63,.08)); border-radius: 2px; animation: eq 1.4s ease-in-out infinite alternate; animation-delay: calc(var(--h) * -0.01s); }
.boot-footer {
  position: absolute; left: 32px; right: 32px; bottom: 24px;
  display: flex; justify-content: space-between; font-family: var(--mono);
  font-size: 9px; letter-spacing: .16em; color: #525866;
}
@keyframes spin { to { transform: rotate(360deg); } }
@keyframes pulse { 0%,100% { opacity: 1; transform: scale(1); } 50% { opacity: .45; transform: scale(.8); } }
@keyframes eq { to { height: calc(var(--h) * .35); } }

/* ==========================================================================
   Header / shell
   ========================================================================== */

.topbar {
  position: relative; z-index: 10;
  height: 64px;
  display: flex; align-items: center; justify-content: space-between;
  padding: 0 20px;
  border-bottom: 1px solid var(--line);
  background: rgba(8, 9, 13, .72);
  backdrop-filter: blur(20px);
}
.brand { display: flex; align-items: center; gap: 11px; min-width: 0; }
.brand-mark { width: 25px; height: 25px; position: relative; display: inline-block; }
.brand-mark i {
  position: absolute; inset: 3px; border-radius: 50%; border: 2px solid var(--a);
  box-shadow: 0 0 12px rgba(255, 159, 63, .3);
}
.brand-mark i + i { inset: 8px 2px 2px 9px; border-color: var(--b); box-shadow: 0 0 12px rgba(78, 215, 255, .25); }
.brand-word { font-size: 16px; font-weight: 900; letter-spacing: -.03em; white-space: nowrap; }
.brand-word span { color: var(--a); }
.brand-tag {
  font-family: var(--mono); font-size: 8px; letter-spacing: .16em; color: var(--muted-2);
  padding-left: 12px; border-left: 1px solid var(--line-strong); white-space: nowrap;
}
.top-meta { display: flex; align-items: center; gap: 20px; font-family: var(--mono); font-size: 10px; color: var(--muted); }
.clock { letter-spacing: .1em; }
.session-bpm { display: flex; align-items: baseline; gap: 5px; letter-spacing: .08em; }
.session-bpm b { font-size: 17px; color: #fff; font-weight: 500; letter-spacing: -.04em; }
.session-bpm small { font-size: 8px; color: var(--muted-2); }
.top-actions { display: flex; align-items: center; gap: 8px; }
.status-chip {
  height: 34px; padding: 0 12px; border-radius: 999px;
  display: flex; align-items: center; gap: 7px;
  border: 1px solid var(--line); background: rgba(255,255,255,.03);
  font-family: var(--mono); font-size: 9px; letter-spacing: .13em;
  transition: background .2s, border-color .2s;
}
.status-chip:hover { background: rgba(255,255,255,.06); border-color: var(--line-strong); }
.status-chip svg { width: 16px; height: 16px; fill: none; }
.status-led { width: 6px; height: 6px; border-radius: 50%; background: #424754; box-shadow: 0 0 0 rgba(0,0,0,0); transition: .25s; }
.status-led.on { background: var(--good); box-shadow: 0 0 12px rgba(157,245,183,.8); }
.status-led.hot { background: var(--a); box-shadow: 0 0 14px var(--a); }
.icon-btn {
  width: 34px; height: 34px; display: grid; place-items: center;
  border: 1px solid var(--line); background: rgba(255,255,255,.03); border-radius: 50%;
  transition: .2s;
}
.icon-btn:hover { background: rgba(255,255,255,.08); }
.icon-btn svg { width: 17px; height: 17px; }

.mobile-tabs { display: none; }

.workspace {
  position: relative; z-index: 2;
  max-width: 1660px; margin: 0 auto; padding: 14px 16px 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 252px minmax(0, 1fr);
  gap: 14px;
  align-items: stretch;
}

/* ==========================================================================
   Deck
   ========================================================================== */

.deck-card {
  position: relative;
  min-width: 0;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background:
    radial-gradient(900px 340px at 50% -10%, rgba(255,255,255,.045), transparent 70%),
    linear-gradient(180deg, rgba(22,25,34,.96), rgba(13,15,21,.97));
  box-shadow: var(--shadow), inset 0 1px rgba(255,255,255,.06);
  overflow: hidden;
}
.deck-card::after {
  content: ""; position: absolute; inset: 0; border-radius: inherit; pointer-events: none;
  background: radial-gradient(420px 200px at 50% 0%, var(--deck-glow), transparent 70%);
  opacity: .55;
}
.deck-a { --accent: var(--a); --accent-hot: var(--a-hot); --accent-dim: var(--a-dim); --deck-glow: rgba(255, 149, 46, .12); }
.deck-b { --accent: var(--b); --accent-hot: var(--b-hot); --accent-dim: var(--b-dim); --deck-glow: rgba(52, 195, 255, .11); }
.deck-card > * { position: relative; z-index: 1; }

.deck-head { display: flex; align-items: center; gap: 10px; height: 45px; padding: 0 2px 8px; }
.deck-letter {
  width: 29px; height: 29px; display: grid; place-items: center; flex: none;
  border-radius: 8px; font-weight: 900; font-size: 14px; color: #0d0d0f;
  background: var(--accent); box-shadow: 0 4px 18px var(--accent-dim);
}
.deck-letter.b { color: #061015; }
.deck-title-wrap { min-width: 0; flex: 1; }
.track-title { margin: 0; font-size: 15px; font-weight: 700; letter-spacing: -.02em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.track-artist { margin: 1px 0 0; font-family: var(--mono); font-size: 8px; letter-spacing: .12em; text-transform: uppercase; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.deck-readout { text-align: right; display: flex; align-items: baseline; gap: 3px; flex: none; }
.bpm-value { font-size: 23px; line-height: 1; font-weight: 500; letter-spacing: -.06em; font-variant-numeric: tabular-nums; }
.bpm-label { font-family: var(--mono); font-size: 7px; color: var(--muted-2); letter-spacing: .1em; }
.key-pill {
  flex: none; font-family: var(--mono); font-size: 8px; letter-spacing: .08em;
  padding: 5px 7px; border-radius: 4px; border: 1px solid var(--line);
  color: var(--muted); background: rgba(255,255,255,.025);
}

.wave-shell {
  position: relative; height: 78px; border-radius: 9px; overflow: hidden;
  background: #090a0e; border: 1px solid rgba(255,255,255,.055);
  box-shadow: inset 0 2px 14px rgba(0,0,0,.55);
  margin-bottom: 12px;
}
.waveform { display: block; width: 100%; height: 100%; cursor: crosshair; touch-action: none; }
.wave-meta {
  position: absolute; left: 8px; right: 8px; bottom: 5px;
  display: flex; justify-content: space-between; align-items: center;
  font-family: var(--mono); font-size: 8px; letter-spacing: .06em; color: rgba(255,255,255,.55);
  pointer-events: none;
}
.wave-badge { padding: 2px 5px; border-radius: 3px; background: rgba(0,0,0,.5); color: var(--accent); font-size: 7px; letter-spacing: .12em; }
.wave-hint {
  position: absolute; right: 8px; top: 6px; font-family: var(--mono); font-size: 7px;
  letter-spacing: .12em; color: rgba(255,255,255,.25); pointer-events: none;
}

.deck-body { display: grid; grid-template-columns: minmax(0, 1.02fr) minmax(0, .98fr); gap: 14px; }
.platter-col { min-width: 0; display: flex; flex-direction: column; align-items: center; }

.platter {
  position: relative; width: min(100%, 262px); aspect-ratio: 1; border-radius: 50%;
  touch-action: none; user-select: none; -webkit-user-select: none;
  cursor: grab; margin-top: 2px;
  filter: drop-shadow(0 16px 22px rgba(0,0,0,.48));
}
.platter:active { cursor: grabbing; }
.platter-ring {
  position: absolute; inset: 0; border-radius: 50%;
  background:
    conic-gradient(from 0deg, rgba(255,255,255,.18), transparent 8%, transparent 92%, rgba(255,255,255,.16)),
    radial-gradient(circle at 50% 50%, transparent 63%, rgba(255,255,255,.03) 64%, rgba(255,255,255,.09) 68%, #0a0b0f 69%, #171a22 100%);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.09), inset 0 8px 16px rgba(255,255,255,.04);
  transition: box-shadow .2s;
}
.platter.touched .platter-ring {
  box-shadow: inset 0 0 0 1px var(--accent), 0 0 30px var(--accent-dim), inset 0 8px 16px rgba(255,255,255,.05);
}
.platter-disc {
  position: absolute; inset: 8.5%; border-radius: 50%;
  background:
    repeating-radial-gradient(circle at 50% 50%, rgba(255,255,255,.028) 0 1px, transparent 1px 4px),
    radial-gradient(circle at 38% 28%, #292d38, #11131a 38%, #050609 76%);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.1), inset 0 0 38px rgba(0,0,0,.9), 0 8px 20px rgba(0,0,0,.5);
  will-change: transform;
}
.platter-disc::before {
  content: ""; position: absolute; inset: 8%; border-radius: 50%;
  border: 1px solid rgba(255,255,255,.05);
}
.grooves {
  position: absolute; inset: 4%; border-radius: 50%;
  background: repeating-radial-gradient(circle at 50% 50%, transparent 0 3px, rgba(255,255,255,.035) 3px 4px);
  mask-image: radial-gradient(circle, transparent 36%, black 38%);
}
.disc-label {
  position: absolute; inset: 30%; border-radius: 50%;
  background:
    radial-gradient(circle at 35% 25%, rgba(255,255,255,.35), transparent 40%),
    linear-gradient(145deg, var(--accent-hot), var(--accent) 55%, #a54a00);
  color: #1a1004; display: flex; flex-direction: column; align-items: center; justify-content: center;
  text-align: center; box-shadow: inset 0 0 0 1px rgba(0,0,0,.25), 0 0 0 5px rgba(0,0,0,.22);
  overflow: hidden;
}
.deck-b .disc-label { background: radial-gradient(circle at 35% 25%, rgba(255,255,255,.45), transparent 40%), linear-gradient(145deg, var(--accent-hot), var(--accent) 55%, #00749b); color: #03151c; }
.label-top, .label-bottom { font-family: var(--mono); font-size: clamp(4px, .52vw, 7px); letter-spacing: .12em; font-weight: 700; }
.label-track { font-size: clamp(9px, 1.05vw, 13px); line-height: 1.02; font-weight: 900; letter-spacing: -.04em; margin: 3px 0; }
.disc-marker {
  position: absolute; width: 3px; height: 10%; left: calc(50% - 1.5px); top: 2%;
  border-radius: 3px; background: var(--accent-hot);
  box-shadow: 0 0 8px var(--accent);
}
.platter-tick { position: absolute; width: 2px; height: 7px; background: rgba(255,255,255,.22); border-radius: 2px; left: calc(50% - 1px); top: 3px; transform-origin: 50% calc(50% + 50% - 3px); }
.platter-tick.t1 { transform: rotate(0deg); }
.platter-tick.t2 { transform: rotate(90deg); }
.platter-tick.t3 { transform: rotate(180deg); }
.platter-tick.t4 { transform: rotate(270deg); }
.platter-indicator {
  position: absolute; width: 5px; height: 5px; border-radius: 50%; background: var(--accent);
  top: 6%; left: calc(50% - 2.5px); box-shadow: 0 0 10px var(--accent);
}
.platter-touch {
  position: absolute; left: 50%; bottom: 9%; transform: translateX(-50%);
  white-space: nowrap; font-family: var(--mono); font-size: 6px; letter-spacing: .12em;
  color: rgba(255,255,255,.34); background: rgba(0,0,0,.55); padding: 4px 7px; border-radius: 999px;
  pointer-events: none; border: 1px solid rgba(255,255,255,.06);
  transition: .2s;
}
.platter.touched .platter-touch { color: var(--accent); border-color: var(--accent-dim); }
.platter:focus-visible { outline-offset: 8px; }

.transport { display: flex; align-items: center; justify-content: center; gap: 9px; margin-top: 12px; }
.transport-btn {
  height: 33px; min-width: 48px; padding: 0 11px; border-radius: 7px;
  border: 1px solid var(--line-strong); background: linear-gradient(#1b1f29, #12151c);
  font-family: var(--mono); font-size: 8px; letter-spacing: .14em; color: var(--muted);
  box-shadow: inset 0 1px rgba(255,255,255,.07), 0 3px 8px rgba(0,0,0,.25);
  transition: .18s;
}
.transport-btn:hover { color: #fff; border-color: rgba(255,255,255,.25); }
.transport-btn.active { color: var(--accent); border-color: var(--accent); box-shadow: 0 0 18px var(--accent-dim), inset 0 1px rgba(255,255,255,.07); }
.play-btn {
  width: 56px; height: 56px; border-radius: 50%; border: 1px solid rgba(255,255,255,.18);
  display: grid; place-items: center;
  background: radial-gradient(circle at 35% 25%, #343945, #12151c 68%);
  box-shadow: 0 8px 18px rgba(0,0,0,.4), inset 0 1px rgba(255,255,255,.12);
  transition: .2s;
}
.play-btn svg { width: 22px; height: 22px; fill: #fff; margin-left: 2px; }
.play-btn:hover { transform: scale(1.04); border-color: var(--accent); }
.play-btn.playing { background: radial-gradient(circle at 35% 25%, var(--accent-hot), var(--accent) 65%, #a34b00); border-color: transparent; box-shadow: 0 0 30px var(--accent-dim), inset 0 1px rgba(255,255,255,.45); }
.deck-b .play-btn.playing { background: radial-gradient(circle at 35% 25%, var(--b-hot), var(--b) 65%, #006f95); }
.play-btn.playing svg { fill: #16100a; }
.deck-b .play-btn.playing svg { fill: #02141a; }
.platter-state {
  display: flex; align-items: center; gap: 7px; margin-top: 9px;
  font-family: var(--mono); font-size: 7px; letter-spacing: .12em; color: var(--muted-2);
}
.state-dot { width: 5px; height: 5px; border-radius: 50%; background: #3b414d; transition: .2s; }
.platter-state.active .state-dot { background: var(--accent); box-shadow: 0 0 8px var(--accent); }
.platter-state.active { color: var(--accent); }
#scratchRateA, #scratchRateB { margin-left: 4px; color: rgba(255,255,255,.35); }

.deck-controls { min-width: 0; display: flex; flex-direction: column; gap: 9px; padding-top: 3px; }
.pitch-strip {
  display: grid; grid-template-columns: 1fr 29px; grid-template-rows: auto 1fr auto;
  gap: 4px 8px; padding: 8px 9px; border-radius: 10px;
  border: 1px solid var(--line); background: rgba(255,255,255,.018);
}
.pitch-head { grid-column: 1; display: flex; justify-content: space-between; align-items: center; font-family: var(--mono); font-size: 7px; letter-spacing: .12em; color: var(--muted-2); }
.pitch-head b { color: var(--accent); font-size: 9px; letter-spacing: 0; font-weight: 500; }
.pitch-fader-wrap { grid-column: 1; grid-row: 2; position: relative; height: 88px; display: flex; justify-content: center; }
.pitch-center { position: absolute; width: 17px; height: 1px; background: rgba(255,255,255,.18); top: 50%; left: 50%; transform: translate(-50%,-50%); pointer-events: none; }
.range-buttons { grid-column: 1 / -1; display: flex; gap: 3px; }
.range-buttons button {
  flex: 1; height: 17px; border: 1px solid var(--line); background: transparent; border-radius: 4px;
  font-family: var(--mono); font-size: 6px; letter-spacing: .05em; color: var(--muted-2);
}
.range-buttons button.active { color: var(--accent); border-color: var(--accent-dim); background: var(--accent-dim); }
.vrange {
  -webkit-appearance: none; appearance: none; background: transparent;
  writing-mode: vertical-lr; direction: rtl;
  width: 24px; height: 100%; padding: 0; margin: 0;
}
.vrange::-webkit-slider-runnable-track {
  width: 4px; border-radius: 4px;
  background: linear-gradient(to top, #2d3240, #101219);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.08);
}
.vrange::-webkit-slider-thumb {
  -webkit-appearance: none; width: 18px; height: 11px; margin-left: -7px; border-radius: 3px;
  background: linear-gradient(#e6e8ee, #8e94a4); border: 1px solid rgba(0,0,0,.5);
  box-shadow: 0 2px 5px rgba(0,0,0,.5), inset 0 1px rgba(255,255,255,.8);
}
.chan-range::-webkit-slider-runnable-track { background: linear-gradient(to top, var(--accent) 0 var(--fill, 82%), #232734 var(--fill, 82%)); }
.chan-range::-webkit-slider-thumb { background: linear-gradient(#fff, #c3c7d1); }
.knob-bank { display: grid; grid-template-columns: repeat(4, 1fr); gap: 5px; }
.knob { display: flex; flex-direction: column; align-items: center; gap: 3px; user-select: none; cursor: ns-resize; }
.knob-dial {
  position: relative; width: 100%; max-width: 46px; aspect-ratio: 1; border-radius: 50%;
  background: radial-gradient(circle at 38% 30%, #343945, #161920 58%, #08090d 100%);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.12), 0 4px 8px rgba(0,0,0,.4);
}
.knob-dial::after {
  content: ""; position: absolute; inset: 17%; border-radius: 50%;
  background: radial-gradient(circle at 38% 30%, #242833, #101219);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.05);
}
.knob-pointer {
  position: absolute; width: 2px; height: 31%; left: calc(50% - 1px); top: 7%;
  background: var(--accent); border-radius: 2px; transform-origin: 50% 139%; z-index: 2;
  box-shadow: 0 0 7px var(--accent);
}
.knob-center { position: absolute; inset: 39%; border-radius: 50%; background: #2a2e39; z-index: 2; box-shadow: inset 0 1px rgba(255,255,255,.15); }
.knob-name { font-family: var(--mono); font-size: 6px; letter-spacing: .1em; color: var(--muted-2); }
.knob-read { font-family: var(--mono); font-size: 7px; color: var(--muted); font-variant-numeric: tabular-nums; }
.knob:hover .knob-dial { border-color: var(--accent); }
.knob.small .knob-dial { max-width: 42px; }
.knob.small { cursor: ns-resize; }

.pads { display: grid; grid-template-columns: repeat(4, 1fr); gap: 5px; }
.pad {
  position: relative; min-width: 0; height: 45px; border-radius: 6px;
  border: 1px solid rgba(255,255,255,.08);
  background: linear-gradient(180deg, #1a1e27, #11141a);
  box-shadow: inset 0 1px rgba(255,255,255,.05), 0 2px 4px rgba(0,0,0,.3);
  padding: 5px 6px 4px; text-align: left; overflow: hidden;
  transition: .14s;
}
.pad:hover { border-color: rgba(255,255,255,.2); }
.pad:active { transform: translateY(1px); }
.pad-key { position: absolute; top: 3px; right: 4px; font-family: var(--mono); font-size: 6px; color: var(--muted-2); }
.pad-label { display: block; font-family: var(--mono); font-size: 7px; letter-spacing: .08em; color: var(--muted); }
.pad-time { display: block; margin-top: 5px; font-family: var(--mono); font-size: 6px; letter-spacing: .02em; color: var(--muted-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cue-pad.set { border-color: var(--accent-dim); background: linear-gradient(180deg, rgba(255,159,63,.15), rgba(255,159,63,.04)); }
.deck-b .cue-pad.set { background: linear-gradient(180deg, rgba(78,215,255,.15), rgba(78,215,255,.04)); }
.cue-pad.set .pad-label, .cue-pad.set .pad-time { color: var(--accent); }
.loop-pad.active { border-color: var(--accent); background: var(--accent-dim); box-shadow: 0 0 16px var(--accent-dim); }
.loop-pad.active .pad-label, .loop-pad.active .pad-time { color: var(--accent); }
.pad.flash { background: var(--accent); }
.pad.flash .pad-label, .pad.flash .pad-time { color: #101010; }

.fx-row { display: flex; align-items: center; gap: 8px; min-height: 28px; }
.fx-toggle {
  height: 26px; padding: 0 10px; border-radius: 5px; border: 1px solid var(--line);
  background: rgba(255,255,255,.025); font-family: var(--mono); font-size: 7px;
  letter-spacing: .13em; color: var(--muted); display: flex; align-items: center; gap: 6px;
}
.fx-led { width: 5px; height: 5px; border-radius: 50%; background: #3b414d; }
.fx-toggle.active { color: var(--accent); border-color: var(--accent); background: var(--accent-dim); }
.fx-toggle.active .fx-led { background: var(--accent); box-shadow: 0 0 8px var(--accent); }
.fx-caption { margin-left: auto; font-family: var(--mono); font-size: 6px; letter-spacing: .1em; color: var(--muted-2); }
.level-meter { position: relative; height: 4px; flex: 1; background: #1c202a; border-radius: 3px; overflow: hidden; }
.level-meter i { position: absolute; inset: 0 auto 0 0; width: 0%; border-radius: 3px; background: linear-gradient(90deg, var(--good), var(--accent) 76%, var(--danger)); transition: width .08s linear; }

/* ==========================================================================
   Mixer
   ========================================================================== */

.mixer-card {
  min-width: 0; padding: 14px 13px; border-radius: var(--radius);
  border: 1px solid var(--line);
  background:
    linear-gradient(180deg, rgba(25,28,38,.94), rgba(11,13,18,.98)),
    radial-gradient(400px 300px at 50% 0%, rgba(255,255,255,.04), transparent);
  box-shadow: var(--shadow), inset 0 1px rgba(255,255,255,.06);
  display: flex; flex-direction: column; gap: 13px;
}
.mixer-head { display: flex; align-items: flex-end; justify-content: space-between; border-bottom: 1px solid var(--line); padding-bottom: 9px; }
.mixer-kicker, .library-kicker, .drawer-kicker { display: block; font-family: var(--mono); font-size: 6px; letter-spacing: .18em; color: var(--muted-2); margin-bottom: 2px; }
.mixer-head h2, .library-head h2, .drawer-head h2 { margin: 0; font-size: 17px; letter-spacing: -.03em; }
.mixer-format { font-family: var(--mono); font-size: 6px; letter-spacing: .1em; color: var(--muted-2); }

.master-block { display: grid; grid-template-columns: 1fr 1fr; gap: 6px 10px; align-items: end; padding-bottom: 11px; border-bottom: 1px solid var(--line); }
.master-label { display: flex; align-items: baseline; gap: 5px; font-family: var(--mono); font-size: 7px; letter-spacing: .1em; color: var(--muted-2); }
.master-label b { margin-left: auto; font-size: 18px; letter-spacing: -.05em; color: #fff; font-weight: 500; }
.master-label small { font-size: 6px; color: var(--muted-2); }
.master-meter { display: flex; gap: 5px; align-items: end; justify-content: flex-end; }
.meter-scale { display: flex; flex-direction: column; justify-content: space-between; height: 34px; font-family: var(--mono); font-size: 5px; color: var(--muted-2); text-align: right; }
.master-bars { display: flex; gap: 3px; height: 34px; align-items: end; }
.master-bars i { display: block; width: 5px; height: 100%; border-radius: 2px; background: linear-gradient(to top, var(--good) 0 42%, #ffc14d 42% 74%, var(--danger) 74%); clip-path: inset(calc(100% - var(--lvl, 0%)) 0 0 0); transition: clip-path .06s linear; }
.master-knob-row { grid-column: 1 / -1; display: flex; align-items: center; justify-content: space-between; margin-top: 3px; }
.sync-all {
  height: 26px; padding: 0 9px; border-radius: 4px; border: 1px solid var(--line);
  background: rgba(255,255,255,.025); font-family: var(--mono); font-size: 6px;
  letter-spacing: .1em; color: var(--muted);
}
.sync-all:hover { color: #fff; border-color: var(--line-strong); }

.channel-strips { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; flex: 1; min-height: 170px; }
.channel-strip { display: flex; flex-direction: column; min-width: 0; }
.chan-head { display: flex; align-items: center; justify-content: space-between; font-family: var(--mono); font-size: 7px; color: var(--muted-2); }
.chan-letter { width: 18px; height: 18px; border-radius: 4px; display: grid; place-items: center; font-size: 9px; font-weight: 900; color: #0c0d10; }
.chan-letter.a { background: var(--a); }
.chan-letter.b { background: var(--b); }
.chan-fader-wrap { flex: 1; min-height: 126px; display: flex; align-items: center; justify-content: center; gap: 8px; padding: 8px 0; }
.chan-range { height: 100%; width: 27px; }
.chan-meter { width: 6px; height: 92%; border-radius: 3px; background: #1c202a; position: relative; overflow: hidden; box-shadow: inset 0 0 0 1px rgba(255,255,255,.04); }
.chan-meter i { position: absolute; inset: auto 0 0 0; height: 0%; background: linear-gradient(to top, var(--good), #ffc14d 70%, var(--danger)); border-radius: 3px; transition: height .07s linear; }
.chan-foot { display: flex; align-items: center; justify-content: space-between; font-family: var(--mono); font-size: 6px; letter-spacing: .1em; color: var(--muted-2); }
.chan-foot b { font-size: 8px; color: var(--muted); font-weight: 500; }

.crossfader-block { padding: 10px 0 5px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.cross-head { display: flex; justify-content: space-between; font-family: var(--mono); font-size: 6px; letter-spacing: .12em; color: var(--muted-2); margin-bottom: 6px; }
.cross-head span:nth-child(2) { color: var(--muted); }
.hrange {
  -webkit-appearance: none; appearance: none; width: 100%; height: 26px; background: transparent; margin: 0;
}
.hrange::-webkit-slider-runnable-track {
  height: 4px; border-radius: 3px;
  background: linear-gradient(90deg, rgba(255,159,63,.7), #292e3a 46% 54%, rgba(78,215,255,.7));
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.07);
}
.hrange::-webkit-slider-thumb {
  -webkit-appearance: none; width: 19px; height: 25px; margin-top: -10px; border-radius: 4px;
  background: linear-gradient(90deg, #e4e7ee, #969cab);
  border: 1px solid rgba(0,0,0,.5);
  box-shadow: 0 3px 7px rgba(0,0,0,.45), inset 0 1px rgba(255,255,255,.8);
}
.cross-marks { display: flex; justify-content: space-between; padding: 0 4px; }
.cross-marks i { width: 1px; height: 3px; background: rgba(255,255,255,.15); }

.mixer-bottom { display: flex; flex-direction: column; gap: 5px; }
.mixer-stat { display: flex; justify-content: space-between; font-family: var(--mono); font-size: 6px; letter-spacing: .09em; color: var(--muted-2); }
.mixer-stat b { color: var(--muted); font-weight: 500; }
.mixer-midi-btn {
  height: 32px; border-radius: 5px; border: 1px solid var(--line);
  background: rgba(255,255,255,.025); font-family: var(--mono); font-size: 6px;
  letter-spacing: .13em; color: var(--muted); display: flex; align-items: center; justify-content: center; gap: 6px;
}
.mixer-midi-btn svg { width: 14px; height: 14px; fill: none; }
.mixer-midi-btn:hover { color: #fff; border-color: var(--line-strong); background: rgba(255,255,255,.05); }

/* ==========================================================================
   Library
   ========================================================================== */

.library-card {
  position: relative; z-index: 2;
  max-width: 1660px; margin: 14px auto 0; padding: 12px 16px 10px;
  border: 1px solid var(--line); border-radius: var(--radius);
  background: linear-gradient(180deg, rgba(17,20,27,.95), rgba(9,10,14,.98));
  box-shadow: 0 20px 50px rgba(0,0,0,.35), inset 0 1px rgba(255,255,255,.05);
}
.library-head { display: flex; align-items: center; gap: 18px; padding-bottom: 9px; border-bottom: 1px solid var(--line); }
.library-title { min-width: 120px; }
.library-head h2 { font-size: 16px; }
.search-box {
  flex: 1; max-width: 360px; height: 29px; border: 1px solid var(--line); border-radius: 5px;
  background: rgba(255,255,255,.025); display: flex; align-items: center; gap: 7px; padding: 0 9px;
}
.search-box svg { width: 13px; height: 13px; color: var(--muted-2); flex: none; }
.search-box input { flex: 1; min-width: 0; border: 0; background: transparent; color: #fff; font-size: 10px; outline: 0; }
.search-box input::placeholder { color: var(--muted-2); }
.library-actions { margin-left: auto; display: flex; align-items: center; gap: 12px; }
.library-count { font-family: var(--mono); font-size: 7px; letter-spacing: .12em; color: var(--muted-2); }
.import-btn {
  height: 29px; padding: 0 11px; border: 1px solid var(--a); border-radius: 5px;
  background: rgba(255,159,63,.08); color: var(--a); font-family: var(--mono);
  font-size: 7px; letter-spacing: .1em; display: flex; align-items: center; gap: 6px;
}
.import-btn svg { width: 13px; height: 13px; }
.import-btn:hover { background: var(--a); color: #15100a; }

.track-list { display: flex; flex-direction: column; max-height: 123px; overflow-y: auto; scrollbar-width: thin; }
.track-row {
  display: grid; grid-template-columns: 30px minmax(170px, 1.4fr) minmax(110px, .8fr) 70px 60px 80px 88px;
  align-items: center; gap: 12px; min-height: 37px; padding: 4px 6px;
  border-bottom: 1px solid rgba(255,255,255,.04);
  transition: background .15s;
}
.track-row:hover { background: rgba(255,255,255,.025); }
.track-cover {
  width: 28px; height: 28px; border-radius: 4px; position: relative; overflow: hidden;
  background: linear-gradient(145deg, var(--cover, #555), #12141a);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.13);
}
.track-cover::after { content: ""; position: absolute; inset: 30%; border-radius: 50%; background: rgba(0,0,0,.45); box-shadow: 0 0 0 1px rgba(255,255,255,.16); }
.track-info { min-width: 0; }
.track-name { margin: 0; font-size: 11px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.track-by { margin: 1px 0 0; font-family: var(--mono); font-size: 7px; letter-spacing: .08em; color: var(--muted-2); text-transform: uppercase; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.track-meta { font-family: var(--mono); font-size: 8px; color: var(--muted); letter-spacing: .04em; }
.track-dur { font-family: var(--mono); font-size: 8px; color: var(--muted-2); }
.track-tag { font-family: var(--mono); font-size: 6px; letter-spacing: .08em; color: var(--muted-2); padding: 3px 5px; border: 1px solid var(--line); border-radius: 3px; width: max-content; }
.track-tag.imported { color: var(--b); border-color: var(--b-dim); }
.load-buttons { display: flex; gap: 4px; justify-content: flex-end; }
.load-btn {
  height: 23px; width: 32px; border-radius: 4px; border: 1px solid var(--line);
  background: rgba(255,255,255,.025); font-family: var(--mono); font-size: 7px; color: var(--muted);
}
.load-btn:hover { color: #0d0d10; background: var(--a); border-color: var(--a); }
.load-btn.b:hover { background: var(--b); border-color: var(--b); }
.track-row.playing-a .load-btn.a, .track-row.playing-b .load-btn.b { color: #0d0d10; background: var(--a); border-color: var(--a); }
.track-row.playing-b .load-btn.b { background: var(--b); border-color: var(--b); }
.library-foot { display: flex; justify-content: space-between; padding-top: 6px; font-family: var(--mono); font-size: 6px; letter-spacing: .09em; color: var(--muted-2); }
.drop-hint { color: rgba(255,159,63,.55); }
.library-note { color: var(--muted-2); }

/* ==========================================================================
   Status bar
   ========================================================================== */

.statusbar {
  position: relative; z-index: 2; max-width: 1660px; margin: 0 auto;
  height: 34px; padding: 0 18px; display: flex; align-items: center; justify-content: space-between;
  font-family: var(--mono); font-size: 6px; letter-spacing: .1em; color: var(--muted-2);
}
.status-left, .status-right { display: flex; align-items: center; gap: 16px; }
.status-item { display: flex; align-items: center; gap: 6px; white-space: nowrap; }
.tiny-led { width: 4px; height: 4px; border-radius: 50%; background: #3b414d; }
.tiny-led.on { background: var(--good); box-shadow: 0 0 7px var(--good); }
kbd {
  display: inline-grid; place-items: center; min-width: 15px; height: 14px; padding: 0 3px;
  border-radius: 3px; border: 1px solid rgba(255,255,255,.12); background: rgba(255,255,255,.04);
  color: var(--muted); font-family: var(--mono); font-size: 6px; margin-right: 2px;
}

/* ==========================================================================
   Drawer
   ========================================================================== */

.drawer-scrim, .modal-scrim {
  position: fixed; inset: 0; z-index: 50; background: rgba(0,0,0,.64);
  backdrop-filter: blur(4px); opacity: 0; visibility: hidden; transition: .3s;
}
.drawer-scrim.open, .modal-scrim.open { opacity: 1; visibility: visible; }
.midi-drawer {
  position: fixed; top: 0; right: 0; bottom: 0; z-index: 55; width: min(420px, 100vw);
  background: linear-gradient(180deg, #141720, #0a0b10 70%);
  border-left: 1px solid var(--line-strong);
  box-shadow: -30px 0 80px rgba(0,0,0,.55);
  transform: translateX(102%); transition: transform .38s cubic-bezier(.65,0,.2,1);
  display: flex; flex-direction: column;
}
.midi-drawer.open { transform: translateX(0); }
.drawer-head { padding: 18px 18px 12px; display: flex; align-items: flex-start; justify-content: space-between; border-bottom: 1px solid var(--line); }
.drawer-head h2 { font-size: 20px; }
.drawer-scroll { overflow-y: auto; padding: 0 18px 26px; }
.drawer-section { padding: 16px 0; border-bottom: 1px solid var(--line); }
.section-title { display: flex; align-items: center; gap: 8px; margin-bottom: 11px; }
.section-title span { font-family: var(--mono); font-size: 7px; color: var(--muted-2); }
.section-title h3 { margin: 0; font-size: 10px; letter-spacing: .12em; font-weight: 600; }
.section-title b { margin-left: auto; font-family: var(--mono); font-size: 6px; letter-spacing: .1em; color: var(--muted-2); font-weight: 500; }
.section-title b.live { color: var(--good); }
.connect-row { display: flex; gap: 6px; margin-bottom: 10px; }
.wide-btn {
  flex: 1; height: 33px; border-radius: 5px; border: 1px solid var(--line);
  background: rgba(255,255,255,.03); font-family: var(--mono); font-size: 7px;
  letter-spacing: .1em; color: var(--muted); display: flex; align-items: center; justify-content: center; gap: 7px;
}
.wide-btn:hover { color: #fff; border-color: var(--line-strong); }
.square-btn { width: 33px; height: 33px; border-radius: 5px; border: 1px solid var(--line); background: rgba(255,255,255,.03); color: var(--muted); }
.field-label { display: block; font-family: var(--mono); font-size: 6px; letter-spacing: .13em; color: var(--muted-2); margin: 9px 0 5px; }
.select-wrap { position: relative; }
.select-wrap select {
  width: 100%; height: 32px; padding: 0 26px 0 9px; border-radius: 5px;
  border: 1px solid var(--line); background: #11141b; color: var(--text);
  font-family: var(--mono); font-size: 8px; letter-spacing: .03em; appearance: none; outline: none;
}
.select-wrap svg { position: absolute; right: 8px; top: 50%; transform: translateY(-50%); width: 13px; height: 13px; color: var(--muted-2); pointer-events: none; }
.microcopy { font-size: 9px; line-height: 1.55; color: var(--muted-2); margin: 7px 0 0; }
.microcopy b { color: var(--muted); font-weight: 500; }
.segmented { display: flex; border: 1px solid var(--line); border-radius: 5px; overflow: hidden; }
.segmented button {
  flex: 1; height: 29px; border: 0; background: transparent; font-family: var(--mono);
  font-size: 6px; letter-spacing: .08em; color: var(--muted-2);
}
.segmented button + button { border-left: 1px solid var(--line); }
.segmented button.active { background: var(--a); color: #17100a; }
.inline-fields { display: flex; align-items: flex-end; gap: 8px; margin-top: 8px; }
.mini-field { flex: 1; display: flex; flex-direction: column; gap: 4px; font-family: var(--mono); font-size: 6px; letter-spacing: .09em; color: var(--muted-2); }
.mini-field input[type="number"] {
  width: 100%; height: 27px; border: 1px solid var(--line); border-radius: 4px;
  background: #11141b; color: #fff; font-family: var(--mono); font-size: 9px; padding: 0 7px; outline: 0;
}
.mini-field input[type="range"] { width: 100%; accent-color: var(--a); height: 27px; }
.mini-value { font-family: var(--mono); font-size: 8px; color: var(--a); padding-bottom: 6px; width: 38px; text-align: right; }
.mapping-grid { display: flex; flex-direction: column; gap: 4px; margin-top: 12px; }
.mapping-row { display: flex; align-items: center; gap: 5px; min-height: 28px; }
.map-name { flex: 1; font-family: var(--mono); font-size: 7px; letter-spacing: .05em; color: var(--muted); }
.learn-btn {
  min-width: 72px; height: 25px; border: 1px solid var(--line); border-radius: 4px;
  background: rgba(255,255,255,.025); display: flex; align-items: center; gap: 5px; padding: 0 6px;
  font-family: var(--mono); font-size: 6px; color: var(--muted-2);
}
.learn-btn.slim { min-width: 46px; }
.learn-btn span { font-size: 5px; opacity: .55; }
.learn-btn b { color: var(--muted); font-weight: 500; font-size: 6px; }
.learn-btn:hover { border-color: var(--line-strong); color: #fff; }
.learn-btn.learning { border-color: var(--a); background: var(--a-dim); animation: learnPulse 1s infinite; }
.learn-btn.learning b { color: var(--a); }
.learn-btn.mapped b { color: var(--good); }
@keyframes learnPulse { 50% { box-shadow: 0 0 14px var(--a-dim); } }
.text-btn {
  border: 0; background: transparent; padding: 5px 0; font-family: var(--mono);
  font-size: 6px; letter-spacing: .1em; color: var(--muted-2); text-align: left;
}
.text-btn:hover { color: var(--a); }
.monitor {
  height: 106px; overflow-y: auto; border: 1px solid var(--line); border-radius: 5px;
  background: #08090d; padding: 6px; font-family: var(--mono); font-size: 7px;
  line-height: 1.55; color: var(--muted);
}
.monitor-empty { color: var(--muted-2); padding: 14px 4px; }
.monitor-empty span { font-size: 6px; color: #454b58; }
.monitor-row { display: flex; gap: 5px; padding: 1px 0; white-space: nowrap; border-bottom: 1px solid rgba(255,255,255,.025); }
.monitor-row .raw { color: var(--muted-2); }
.monitor-row .type { color: var(--b); }
.monitor-row .ch { color: var(--a); }
.monitor-row .act { color: var(--good); }
.monitor-row .none { color: #555b69; }
.demo-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 5px; margin-top: 10px; }
.demo-btn {
  height: 29px; border: 1px solid var(--line); border-radius: 4px; background: rgba(255,255,255,.025);
  font-family: var(--mono); font-size: 6px; letter-spacing: .09em; color: var(--muted);
}
.demo-btn:hover { border-color: var(--line-strong); color: #fff; }
.demo-btn.accent { color: var(--a); border-color: var(--a-dim); background: var(--a-dim); }
.demo-btn.active { background: var(--a); color: #17100a; }

/* ==========================================================================
   Help modal
   ========================================================================== */

.help-modal {
  position: fixed; z-index: 55; top: 50%; left: 50%; transform: translate(-50%, -46%) scale(.98);
  width: min(860px, calc(100vw - 36px)); max-height: calc(100vh - 70px); overflow-y: auto;
  border-radius: 16px; border: 1px solid var(--line-strong);
  background: linear-gradient(180deg, #171a23, #0b0c11 80%);
  box-shadow: 0 50px 130px rgba(0,0,0,.7);
  opacity: 0; visibility: hidden; transition: .3s;
}
.help-modal.open { opacity: 1; visibility: visible; transform: translate(-50%, -50%) scale(1); }
.help-head { display: flex; align-items: flex-start; justify-content: space-between; padding: 20px 22px 14px; border-bottom: 1px solid var(--line); position: sticky; top: 0; background: rgba(23,26,35,.95); backdrop-filter: blur(10px); z-index: 2; }
.help-head h2 { margin: 0; font-size: 24px; letter-spacing: -.04em; }
.help-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1px; background: var(--line); }
.help-card { background: #0e1016; padding: 20px 22px; min-height: 145px; }
.help-num { font-family: var(--mono); font-size: 8px; color: var(--a); letter-spacing: .15em; }
.help-card h3 { font-size: 11px; letter-spacing: .08em; margin: 5px 0 8px; }
.help-card p { font-size: 10px; line-height: 1.65; color: var(--muted); margin: 0; }
.help-diagram { display: flex; align-items: center; gap: 5px; margin-top: 12px; flex-wrap: wrap; }
.help-diagram span { font-family: var(--mono); font-size: 6px; letter-spacing: .08em; padding: 4px 6px; border: 1px solid var(--line); border-radius: 3px; color: var(--muted); }
.help-diagram i { color: var(--a); font-style: normal; font-size: 9px; }
.shortcut-list { display: flex; flex-direction: column; gap: 6px; margin-top: 8px; font-size: 9px; color: var(--muted); }
.shortcut-list span { display: flex; align-items: center; gap: 3px; }
.shortcut-list kbd { margin-right: 3px; }

/* ==========================================================================
   Toast / drop
   ========================================================================== */

.toast-stack { position: fixed; z-index: 70; left: 50%; bottom: 48px; transform: translateX(-50%); display: flex; flex-direction: column; gap: 6px; align-items: center; pointer-events: none; }
.toast {
  padding: 9px 14px; border-radius: 5px; border: 1px solid var(--line-strong);
  background: rgba(19,22,30,.94); backdrop-filter: blur(10px);
  box-shadow: 0 10px 30px rgba(0,0,0,.4); font-family: var(--mono); font-size: 8px;
  letter-spacing: .06em; color: #fff; animation: toastIn .25s ease-out, toastOut .3s ease-in 3s forwards;
}
.toast b { color: var(--a); font-weight: 500; }
.toast.error b { color: var(--danger); }
@keyframes toastIn { from { opacity: 0; transform: translateY(7px); } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-5px); } }
.drop-overlay {
  position: fixed; inset: 0; z-index: 80; background: rgba(6,7,10,.8); backdrop-filter: blur(8px);
  display: grid; place-items: center; opacity: 0; visibility: hidden; transition: .2s;
}
.drop-overlay.open { opacity: 1; visibility: visible; }
.drop-card {
  width: min(420px, 86vw); padding: 48px 24px; border: 1px dashed rgba(255,159,63,.6);
  border-radius: 16px; background: rgba(255,159,63,.06); text-align: center;
  display: flex; flex-direction: column; align-items: center; gap: 9px;
}
